using TomasAI.IFM.Domain.Trade.Futures.Option.Position.Query.Actor;using TomasAI.IFM.Domain.Trade.Shared.Futures.Option.Position;using TomasAI.IFM.Domain.Trade.Shared.Model;using TomasAI.IFM.Shared.Domain;using TomasAI.IFM.Shared.EventSourcing;
namespace TomasAI.IFM.Domain.Trade.Futures.Option.Position.Query.Extensions;
public static class PositionQueryHandlers
{public static ValueTask ExecuteAsync(this GetIronCondorOptionTradePositionQuery q,IFuturesOptionPositionQueryContext c,CancellationToken t)=>One(q,c,TradeStrategyKind.IronCondor,t);public static ValueTask ExecuteAsync(this GetVerticalSpreadOptionTradePositionQuery q,IFuturesOptionPositionQueryContext c,CancellationToken t)=>One(q,c,TradeStrategyKind.VerticalSpread,t);public static ValueTask ExecuteAsync(this GetIronCondorOptionTradePositionHistoryQuery q,IFuturesOptionPositionQueryContext c,CancellationToken t)=>Many(q,c,TradeStrategyKind.IronCondor,t);public static ValueTask ExecuteAsync(this GetVerticalSpreadOptionTradePositionHistoryQuery q,IFuturesOptionPositionQueryContext c,CancellationToken t)=>Many(q,c,TradeStrategyKind.VerticalSpread,t);static async ValueTask One(StrategyPositionQueryBase<StrategyPositionSnapshot>q,IFuturesOptionPositionQueryContext c,TradeStrategyKind k,CancellationToken t){var v=await c.DbFactory.TradeDb.GetStrategyPositionAsync(q.PositionId,t);if(v?.StrategyKind!=k)v=null;await c.ReplyAsync(q.Subject.ThreadId,q.Subject.Verb,new ServiceResult<StrategyPositionSnapshot?>(v));}static async ValueTask Many(PositionHistoryQuery q,IFuturesOptionPositionQueryContext c,TradeStrategyKind k,CancellationToken t){var p=await c.DbFactory.TradeDb.GetStrategyPositionHistoryAsync(q.PositionId.PositionId,q.FromUtc,q.ToUtc,q.PageSize,q.PagingState,t);await c.ReplyAsync(q.Subject.ThreadId,q.Subject.Verb,new ServiceResult<StrategyPositionSnapshot[]>(p.Items.Where(x=>x.StrategyKind==k).ToArray()));}}
